begin transaction read only;
select jsonb_build_object('captured_at',now(),'relations',(select jsonb_agg(jsonb_build_object('name',c.relname,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid))) from pg_constraint k where k.conrelid=c.oid))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('domain_events','euromillions_draw_charges','euromillions_draws','euromillions_keys','euromillions_participations','event_partners','event_registrations','member_motorcycles','treasury_accounts','treasury_categories','treasury_transactions')),'enums',(select jsonb_agg(jsonb_build_object('name',t.typname,'values',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid))) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype='e'));
rollback;
